172:           const m = new THREE.Mesh(new THREE.PlaneGeometry(w - 0.5, h - 0.2), std(0x6d6a5b, 0.9));
173:           m.rotation.x = -Math.PI / 2; m.position.set(x + dx + (dx === 0 ? i * 0.9 : 0), 0.024, z + dz + (dz === 0 ? i * 0.9 : 0));
174:           this.scene.add(m);
