6: const matCache = new Map();
7: export function std(color, rough = 0.86, metal = 0, extra = {}) {
8:   const key = `${color}|${rough}|${metal}|${JSON.stringify(extra)}`;
9:   if (matCache.has(key)) return matCache.get(key);
10:   const m = new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal, ...extra });
11:   matCache.set(key, m);
12:   return m;
13: }
14: function glow(color, intensity = 1) {
15:   return new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: intensity, roughness: 0.7 });
16: }
