112:     // river bank mud
113:     const bank = new THREE.Mesh(new THREE.PlaneGeometry(340, 12), std(0x3a3c30, 1));
114:     bank.rotation.x = -Math.PI / 2; bank.position.set(0, -0.005, 100); this.scene.add(bank);
