48:       const first = sex === 'f' ? pick(rng, FIRST_NAMES_F) : pick(rng, FIRST_NAMES_M);
49:       const last = pick(rng, LAST_NAMES);
50:       name = `${first} ${last}`;
51:       if (!used.has(name)) break;
52:     }
53:     used.add(name);
54:     const age = randInt(rng, 18, 78);
55:     const job = pick(rng, ['Machinist','Nurse','Teacher','Clerk','Welder','Mechanic','Cook','Bus driver','Accountant','Carpenter','Pharmacist','Janitor','Farmer','Shop owner','Bank teller','Electrician','Plumber','Sawmill worker','Dispatcher','Security guard','Retired','Unemployed']);
56:     const personality = pick(rng, PERSONALITIES);
57:     const belief = rng() < 0.32 ? 'Ninth Hour (believer)' : rng() < 0.1 ? 'Ninth Hour (Awakened)' : rng() < 0.4 ? 'lapsed' : rng() < 0.5 ? 'none' : 'Protestant';
58:     const sectRank = belief.startsWith('Ninth Hour') ? pick(rng, ['lay', 'lay', 'lay', 'choir', 'deacon']) : 'none';
59:     list.push({
60:       id: `c${i}`, name, sex, age, job, personality, belief, sectRank,
61:       secret: pick(rng, SECRETS), trust: randInt(rng, 35, 65),
62:       fear: randInt(rng, 10, 80), grief: randInt(rng, 0, 30),
63:       home: pick(rng, ['1st Street','2nd Street','Mill Row','Cedar Lane','Chapel Row','Foundry Hill','Riverside','Elm Court']),
64:       memory: [], interviewed: false, alive: true, missing: false,
65:     });
66:   }
67:   return list;
