202:   addCollider(minX, maxX, minZ, maxZ, tag = 'solid') {
203:     this.colliders.push({ minX, maxX, minZ, maxZ, tag });
204:   }
205:   addColliderAt(x, z, w, d, tag) { this.addCollider(x - w / 2, x + w / 2, z - d / 2, z + d / 2, tag); }
206: 
207:   collides(x, z, r = 0.34) {
208:     if (x < -112 || x > 112 || z < -112 || z > 100) return true;
209:     for (const c of this.colliders) {
210:       if (x + r > c.minX && x - r < c.maxX && z + r > c.minZ && z - r < c.maxZ) return true;
211:     }
212:     return false;
213:   }
