358:   makeHouse(x, z, rng) {
359:     const w = 7.5 + rng() * 3.2, d = 7 + rng() * 3.2, h = 4.2 + rng() * 1.8;
360:     const colors = [0x5e5a4c, 0x6c6150, 0x555b51, 0x6b5b4c, 0x4f5654, 0x665a4f];
361:     const g = new THREE.Group(); this.scene.add(g);
362:     const wall = std(colors[Math.floor(rng() * colors.length)], 0.93);
363:     this.makeBox(g, x, h / 2, z, w, h, d, wall);
364:     // gable roof
365:     const roof = new THREE.Mesh(new THREE.ConeGeometry(Math.max(w, d) * 0.72, 2.3, 4), std(0x2c2a25, 0.95));
366:     roof.rotation.y = Math.PI / 4; roof.position.set(x, h + 1.05, z); roof.scale.set(1, 0.9, d / w); roof.castShadow = true; g.add(roof);
367:     this.addColliderAt(x, z, w, d, 'house');
368:     this.addWindows(x, z, w, d, h, 'south', 0.15);
369:     // porch
370:     this.makeBox(g, x, 2.6, z + d / 2 + 0.7, 3.2, 0.16, 1.4, std(0x39362e, 0.9));
371:     this.makeBox(g, x, 0.08, z + d / 2 + 0.7, 3.2, 0.15, 1.4, std(0x4a473e, 0.9));
372:     this.makeBox(g, x + 1.2, 1.3, z + d / 2 + 1.3, 0.12, 2.6, 0.12, std(0x2f2b24, 0.9));
373:     this.makeBox(g, x - 1.2, 1.3, z + d / 2 + 1.3, 0.12, 2.6, 0.12, std(0x2f2b24, 0.9));
374:     // porch bulb
375:     const bulbMat = glow(0xd9b77c, 0.5); this.lampMaterials.push(bulbMat);
376:     const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.11, 6, 6), bulbMat); bulb.position.set(x, 2.45, z + d / 2 + 0.5); g.add(bulb);
377:     // chimney
378:     if (rng() < 0.6) this.makeBox(g, x + w * 0.27, h + 1.3, z - d * 0.2, 0.55, 2.2, 0.55, std(0x4a3d33, 0.95));
379:     // parked car sometimes
380:     if (rng() < 0.4) this.makeCar(x - w / 2 - 2.2, z + d / 2 + 3.2, rng, false);
381:   }
