115: 
116:     // wooded perimeter
117:     const trunk = std(0x2f2b22, 0.95), pine = std(0x1f2b23, 0.94), pine2 = std(0x28332a, 0.94);
118:     for (let i = 0; i < 120; i++) {
119:       const side = i % 4;
120:       let x, z;
121:       if (side === 0) { x = -160 + Math.random() * 320; z = -124 - Math.random() * 18; }
122:       else if (side === 1) { x = -160 + Math.random() * 320; z = 104 + Math.random() * 6; }
123:       else if (side === 2) { x = -128 - Math.random() * 26; z = -110 + Math.random() * 210; }
124:       else { x = 118 + Math.random() * 26; z = -110 + Math.random() * 210; }
125:       const s = 0.8 + Math.random() * 1.8;
126:       const g = new THREE.Group(); g.position.set(x, 0, z);
127:       const t = new THREE.Mesh(new THREE.CylinderGeometry(0.14 * s, 0.22 * s, 2.2 * s, 5), trunk); t.position.y = 1.1 * s; g.add(t);
128:       for (let k = 0; k < 3; k++) {
129:         const cone = new THREE.Mesh(new THREE.ConeGeometry((1.25 - k * 0.28) * s, 2.2 * s, 6), k % 2 ? pine : pine2);
130:         cone.position.y = 2.1 * s + k * 1.0 * s; g.add(cone);
131:       }
132:       this.scene.add(g);
