215:   makeBox(parent, x, y, z, w, h, d, material, cast = true) {
216:     const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
217:     m.position.set(x, y, z); m.castShadow = cast; m.receiveShadow = true; parent.add(m); return m;
218:   }
219:   makeCylinder(parent, x, y, z, r1, r2, h, material, seg = 10) {
220:     const m = new THREE.Mesh(new THREE.CylinderGeometry(r1, r2, h, seg), material);
221:     m.position.set(x, y, z); m.castShadow = true; m.receiveShadow = true; parent.add(m); return m;
222:   }
223:   makePlane(parent, x, y, z, w, h, material, rx = -Math.PI / 2, ry = 0) {
224:     const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), material);
225:     m.position.set(x, y, z); m.rotation.set(rx, ry, 0); m.receiveShadow = true; parent.add(m); return m;
226:   }
227:   sign(parent, text, x, y, z, w, h, opts = {}) {
228:     const tex = labelTexture(text, { w: 640, h: 140, bg: opts.bg || '#0b0e0e', color: opts.color || '#d7cdb7', borderColor: opts.borderColor || 'rgba(190,178,150,.4)', font: opts.font });
229:     const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ map: tex, transparent: true }));
230:     m.position.set(x, y, z); m.rotation.y = opts.ry || 0; parent.add(m); return m;
231:   }
