383:   makeCar(x, z, rng, police = false) {
384:     const g = new THREE.Group(); g.position.set(x, 0, z); g.rotation.y = rng() * Math.PI; this.scene.add(g);
385:     const colors = [0x272b2b, 0x3d3a35, 0x22302f, 0x4a3c32, 0x59574e];
386:     const body = std(police ? 0x20292b : colors[Math.floor(rng() * colors.length)], 0.42, 0.3);
387:     this.makeBox(g, 0, 0.55, 0, 4.3, 0.55, 1.85, body);
388:     this.makeBox(g, -0.2, 1.02, 0, 2.15, 0.55, 1.62, std(0x1a2022, 0.3, 0.4));
389:     const wheel = std(0x0c0d0d, 0.9);
390:     for (const [wx, wz] of [[-1.4, -0.95], [1.4, -0.95], [-1.4, 0.95], [1.4, 0.95]]) {
391:       const wheelM = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.24, 10), wheel);
392:       wheelM.rotation.z = Math.PI / 2; wheelM.position.set(wx, 0.36, wz); g.add(wheelM);
393:     }
394:     const lm = glow(police ? 0x9fc7d6 : 0xd9c49a, 0.4);
395:     for (const wz of [-0.62, 0.62]) {
396:       const hl = new THREE.Mesh(new THREE.SphereGeometry(0.1, 6, 6), lm); hl.position.set(2.16, 0.62, wz); g.add(hl);
397:     }
398:     const tail = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.14, 0.4), glow(0x8d2418, 0.6)); tail.position.set(-2.16, 0.62, 0.55); g.add(tail);
399:     if (police) {
400:       const bar = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.12, 0.5), glow(0x6f1a12, 0.6)); bar.position.set(-0.2, 1.4, 0); g.add(bar);
401:     }
402:     this.addColliderAt(x, z, 4.6, 2.1, 'car');
403:     return g;
404:   }
