272:   frontPos(loc) {
273:     const { x, z, w, d, door } = loc;
274:     if (door === 'east') return { x: x + w / 2 + 0.06, z, ry: Math.PI / 2, nz: 0 };
275:     if (door === 'west') return { x: x - w / 2 - 0.06, z, ry: -Math.PI / 2, nz: 0 };
276:     if (door === 'north') return { x, z: z - d / 2 - 0.06, ry: Math.PI, nz: 0 };
277:     return { x, z: z + d / 2 + 0.06, ry: 0, nz: 0 };
278:   }
