227:   sign(parent, text, x, y, z, w, h, opts = {}) {
228:     const tex = labelTexture(text, { w: 640, h: 140, bg: opts.bg || '#0b0e0e', color: opts.color || '#d7cdb7', borderColor: opts.borderColor || 'rgba(190,178,150,.4)', font: opts.font });
229:     const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ map: tex, transparent: true }));
230:     m.position.set(x, y, z); m.rotation.y = opts.ry || 0; parent.add(m); return m;
231:   }
