233:   makeSolidBuilding(id, loc) {
234:     const g = new THREE.Group();
235:     this.scene.add(g);
236:     const { x, z, w, d, h } = loc;
237:     const wall = std(loc.color, 0.9);
238:     const trim = std(0x6b675c, 0.9);
239:     this.makeBox(g, x, h / 2, z, w, h, d, wall);
240:     this.makeBox(g, x, h + 0.18, z, w + 0.9, 0.42, d + 0.9, std(0x262827, 0.95));
241:     this.addColliderAt(x, z, w, d, 'building');
242:     this.addWindows(x, z, w, d, h, loc.door || 'south', 0.18);
243:     const front = this.frontPos(loc);
244:     this.sign(g, loc.name.toUpperCase(), front.x, 3.5, front.z, Math.min(w * 0.72, 9), 1.15, { ry: front.ry });
245:     // awning + steps
246:     this.makeBox(g, front.x, 3.0, front.z + (front.nz || 0), Math.min(w * 0.7, 9), 0.18, 1.5, trim);
247:     this.makeBox(g, front.x, 0.12, front.z, 3.4, 0.24, 1.4, trim);
248:     return g;
249:   }
