391:       const wheelM = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.24, 10), wheel);
392:       wheelM.rotation.z = Math.PI / 2; wheelM.position.set(wx, 0.36, wz); g.add(wheelM);
