452:   makeRiverbank() {
453:     const g = new THREE.Group(); this.scene.add(g);
454:     this.makePlane(g, 36, 0.0, 96, 60, 24, std(0x3a3b2f, 0.98));
455:     for (let i = 0; i < 18; i++) this.makeTree(14 + Math.random() * 46, 88 + Math.random() * 10, 0.7 + Math.random() * 0.9);
456:     // concrete flood wall
457:     this.makeBox(g, 36, 0.55, 104, 60, 1.1, 0.5, std(0x55564c, 0.95));
458:     this.addCollider(6, 66, 103.6, 104.4, 'wall');
