280:   makeEnterable(id, loc) {
281:     const g = new THREE.Group(); this.scene.add(g);
282:     const { x, z, w, d, h } = loc;
283:     const wall = std(loc.color, 0.9);
284:     const inner = std(0x5b5950, 0.95);
285:     const floorMat = std(0x3a3a33, 0.88);
286:     const t = 0.42, doorW = 3.1;
287:     const door = loc.door || 'south';
288:     // floor + ceiling
289:     this.makeBox(g, x, -0.04, z, w - 0.1, 0.18, d - 0.1, floorMat, false);
290:     this.makeBox(g, x, h - 0.12, z, w, 0.26, d, std(0x2e302c, 0.95));
291:     // walls
292:     if (door === 'south' || door === 'north') {
293:       const frontZ = z + (door === 'south' ? d / 2 : -d / 2);
294:       const backZ = z + (door === 'south' ? -d / 2 : d / 2);
295:       this._wall(g, x - (w / 2 + doorW / 2) / 2 - 0.0, frontZ, (w - doorW) / 2, h, t, wall);
296:       this._wall(g, x + (w / 2 + doorW / 2) / 2, frontZ, (w - doorW) / 2, h, t, wall);
297:       this._wall(g, x, backZ, w, h, t, wall);
298:       this._wall(g, x - w / 2, z, t, h, d, wall);
299:       this._wall(g, x + w / 2, z, t, h, d, wall);
300:       const lintel = new THREE.Mesh(new THREE.BoxGeometry(doorW, 1.0, t), wall);
301:       lintel.position.set(x, h - 0.5, frontZ); g.add(lintel);
302:     } else {
303:       const frontX = x + (door === 'east' ? w / 2 : -w / 2);
304:       const backX = x - (door === 'east' ? w / 2 : -w / 2);
305:       this._wall(g, frontX, z - (d / 2 + doorW / 2) / 2 - 0.0, t, h, (d - doorW) / 2, wall);
306:       this._wall(g, frontX, z + (d / 2 + doorW / 2) / 2, t, h, (d - doorW) / 2, wall);
307:       this._wall(g, backX, z, t, h, d, wall);
308:       this._wall(g, x, z - d / 2, w, h, t, wall);
309:       this._wall(g, x, z + d / 2, w, h, t, wall);
310:       const lintel = new THREE.Mesh(new THREE.BoxGeometry(t, 1.0, doorW), wall);
311:       lintel.position.set(frontX, h - 0.5, z); g.add(lintel);
312:     }
313:     // interior shell trim
314:     this.makeBox(g, x, 0.82, z - d / 2 + 0.25, w - 1, 1.55, 0.06, inner, false);
315:     this.makeBox(g, x, 0.82, z + d / 2 - 0.25, w - 1, 1.55, 0.06, inner, false);
316:     // roof cap
317:     this.makeBox(g, x, h + 0.1, z, w + 0.8, 0.35, d + 0.8, std(0x2a2c29, 0.92));
318:     // facade sign & awning
319:     const front = this.frontPos(loc);
320:     this.sign(g, loc.name.toUpperCase(), front.x, 3.9, front.z, Math.min((door === 'east' || door === 'west' ? d : w) * 0.7, 10), 1.1, { ry: front.ry });
321:     if (door === 'south' || door === 'north') {
322:       this.makeBox(g, x, 3.2, z + (door === 'south' ? d / 2 + 0.55 : -d / 2 - 0.55), Math.min(w * 0.74, 11), 0.16, 1.3, std(0x403a30, 0.92));
323:       this.makeBox(g, x, 0.08, z + (door === 'south' ? d / 2 + 0.5 : -d / 2 - 0.5), doorW + 0.6, 0.16, 1.1, std(0x5b564a, 0.9));
324:     } else {
325:       this.makeBox(g, x + (door === 'east' ? w / 2 + 0.5 : -w / 2 - 0.5), 3.2, z, 1.3, 0.16, Math.min(d * 0.7, 11), std(0x403a30, 0.92));
326:     }
327:     // windows (decoration, exterior)
328:     this.addWindows(x, z, w, d, h, door, 0.3);
329:     // doorway frame
330:     if (door === 'south') this.makeBox(g, x, 0.12, z + d / 2 - 0.1, doorW + 0.8, 0.22, 0.6, std(0x6a6252, 0.8));
331:     if (door === 'east') this.makeBox(g, x + w / 2 - 0.1, 0.12, z, 0.6, 0.22, doorW + 0.8, std(0x6a6252, 0.8));
332: 
333:     // interior light
334:     const light = new THREE.PointLight(0xd8b27a, 0, w + d + 12, 2);
335:     light.position.set(x, h - 1.0, z); this.scene.add(light);
336:     for (let i = 0; i < 2; i++) {
337:       const panel = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.08, 0.7), new THREE.MeshBasicMaterial({ color: 0xffe2b0 }));
338:       panel.position.set(x + (i ? 3 : -3), h - 0.28, z); panel.material.transparent = true; panel.material.opacity = 0.72; this.scene.add(panel);
339:     }
340:     this.interiors.push({ id, loc, light });
341:     this.addColliderAt(x, z, 0.01, 0.01, 'noop');
342:     return g;
343:   }
